export const dubFirstSalePipe = defineMaterializedView("dub_first_sale_pipe", {
  datasource: dubFirstSaleMv,
  nodes: [
    node({
      name: "mv",
      sql: `
SELECT
workspace_id,
link_id,
customer_id,
minState(timestamp) AS first_sale_state
FROM dub_sale_events_mv
GROUP BY
workspace_id,
link_id,
customer_id
      `,
    }),
  ],
});

export const getApiLogById = definePipe("get_api_log_by_id", {
  params: {
    id: p.string(),
    workspaceId: p.string(),
  },
  nodes: [
    node({
      name: "endpoint",
      sql: `
SELECT
id,
timestamp,
method,
path,
route_pattern,
status_code,
duration,
user_agent,
request_body,
query_params,
response_body,
token_id,
user_id,
request_type
FROM dub_api_logs_id
WHERE
id = {{ String(id) }}
AND workspace_id = {{ String(workspaceId) }}
LIMIT 1
      `,
    }),
  ],
  endpoint: true,
  output: {
    id: t.string(),
    timestamp: t.string(),
    method: t.string(),
    path: t.string(),
    route_pattern: t.string(),
    status_code: t.string(),
    duration: t.string(),
    user_agent: t.string(),
    request_body: t.string(),
    query_params: t.string(),
    response_body: t.string(),
    token_id: t.string(),
    user_id: t.string(),
    request_type: t.string(),
  },
});

